/// <summary>
/// The relauncher spawns a fake app, waits for the sidecar to be
/// consumed, and exits 0. We use /bin/rm as the fake app — it deletes
/// the handoff sidecar and exits immediately. The argv round-trip test
/// already verifies the argv shape; this test verifies the arrival
/// detection loop and success exit code.
/// </summary>
[Fact]
public async Task Relauncher_SpawnsFakeApp_WithCorrectArgv_AndExitsZero()
{
    using var repo = TestRepository.Create();

    var handoffPath = Path.Combine(repo.Root, ".relay", "restart-handoff.json");

    // Fake app: /bin/rm deletes the handoff and exits 0. The argv is
    // [rm, -f, handoffPath] — the Relauncher must pass these as
    // individual ArgumentList entries.
    var appCmd = new[] { "/bin/rm", "-f", handoffPath };

    _ = RestartHandoff.Write(
        repo.Root,
        new RelayTaskOutcome("test", RelayTaskOutcomeStatus.Committed, "hash", "sha", null),
        "drain-test",
        pendingCount: 1,
        appRestartCommand: appCmd);

    Assert.True(File.Exists(handoffPath));

    var time = new ManualTimeProvider();
    var task = VisualRelay.Relauncher.Relauncher.RunAsync(repo.Root, timeProvider: time);

    // Advance virtual time in increments so the polling loop runs.
    // /bin/rm deletes the handoff and exits immediately; the polling
    // loop should see the handoff gone (or child exited + handoff gone)
    // on the first check after a small virtual-time tick.
    for (var i = 0; i < 30 && !task.IsCompleted; i++)
    {
        time.Advance(TimeSpan.FromMilliseconds(300));
        System.Threading.Thread.Sleep(1); // yield to let child process run
    }

    Assert.True(task.IsCompleted,
        "Relauncher.RunAsync never completed — child may not have deleted handoff");

    var exitCode = await task;
    Assert.Equal(0, exitCode);

    // The handoff was deleted by the child.
    Assert.False(File.Exists(handoffPath));
}

